	scopyWithin.ndarray( 2, 2, 1, 2, x, 1, null ); // $ExpectError
	scopyWithin.ndarray( 2, 2, 1, 2, x, 1, undefined ); // $ExpectError
	scopyWithin.ndarray( 2, 2, 1, 2, x, 1, [] ); // $ExpectError
